using namespace std;

typedef long long ll;
typedef long double ld;

#define fastInp cin.tie(0); cout.tie(0); ios_base::sync_with_stdio(0);

vector<ll> vec;
ll n;

const ll CHECK = 512;

int solve() {

	cin >> n;

	vec.resize(n);
	for (auto& c : vec) cin >> c;

	vector<ll> dp(1);

	ll bst = 0;
	for (int i = 0; i < n; i++) {
		ll cur = 0;
		dp.push_back(1);
		for (int j = i - 1; j >= max(0ll, i - CHECK); j--) {
			if ((vec[i] ^ j) > (vec[j] ^ i)) {
				dp.back() = max(dp.back(), dp[j + 1] + 1);
			}
		}

		bst = max(bst, dp.back());
	}

	cout << bst << "\n";

	return 0;
}

int main(){
    fastInp;
    int t;
    cin >> t;
    while(t--) solve();
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const int maxlog = 30;
const int maxn = 300000;

int nodes[maxn * maxlog + maxlog][2];
int nodev[maxn * maxlog + maxlog][2];
int last;

inline int f() {
    nodes[last][0] = 0;
    nodes[last][1] = 0;
    nodev[last][0] = 0;
    nodev[last][1] = 0;
    return last++;
}

int solve() {
    int n;
    cin >> n;
    vector <int> v(n);
    for (auto& i : v) cin >> i;
    int ans = 0;
    last = 0;
    f();
    for (int i = 0; i < n; i++) {
        int a = 0;
        int b = v[i] ^ i;
        int c = i;
        int getmax = 0;
        for (int j = maxlog; j >= 0; j--) {
            if (nodes[a][((b >> j) & 1) ^ 1]) getmax = max(getmax, nodev[nodes[a][((b >> j) & 1) ^ 1]][(((b ^ c) >> j) & 1) ^ 1]);
            if (!nodes[a][(b >> j) & 1]) break;
            a = nodes[a][(b >> j) & 1];
        }
        ans = max(ans, getmax + 1);
        a = 0;
        b = v[i] ^ i;
        c = i;
        int d = getmax + 1;
        for (int j = maxlog; j >= 0; j--) {
            if (!nodes[a][(b >> j) & 1]) nodes[a][(b >> j) & 1] = f();
            nodev[nodes[a][(b >> j) & 1]][(c >> j) & 1] = max(nodev[nodes[a][(b >> j) & 1]][(c >> j) & 1], d);
            a = nodes[a][(b >> j) & 1];
        }
    }
    cout << ans << "\n";
    return 0;
}

int main() {
    ios::sync_with_stdio(0); cin.tie(0);
    int t;
    cin >> t;
    while (t--) solve();
}

#include <iostream>
#include <vector>
#include <cmath>
#include <array>

using namespace std;
const int INF = 1e9;

inline int min(int a, int b) {
    if (a < b) return a;
    return b;
}

inline int max(int a, int b) {
    if (a > b) return a;
    return b;
}

inline void solve1() {
    int n, k, cnt = 0;
    cin >> n >> k;
    vector <vector <int>> a(n, vector <int>(n)), pref(n + 1, vector <int>(n + 1));
    vector <array <int, 4>> all(n * n, { INF, -INF, INF, -INF });
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> a[i][j]; --a[i][j];
            all[a[i][j]][0] = min(all[a[i][j]][0], i);
            all[a[i][j]][1] = max(all[a[i][j]][1], i);
            all[a[i][j]][2] = min(all[a[i][j]][2], j);
            all[a[i][j]][3] = max(all[a[i][j]][3], j);
        }
    }
    for (auto& i : all) {
        if (i[0] != INF) ++cnt;
    }
    if (cnt <= k) {
        cout << k - cnt;
        return;
    }
    for (int len = 1; len <= n; ++len) {
        for (auto& i : all) {
            if (i[0] == INF) continue;
            int mn_x = i[0], mx_x = i[1], mn_y = i[2], mx_y = i[3];
            mx_x = max(0, mx_x - len + 1);
            mx_y = max(0, mx_y - len + 1);
            mn_x = min(mn_x, n - len);
            mn_y = min(mn_y, n - len);
            if (mx_x <= mn_x && mx_y <= mn_y) {
                ++pref[mx_x][mx_y];
                --pref[mx_x][mn_y + 1];
                --pref[mn_x + 1][mx_y];
                ++pref[mn_x + 1][mn_y + 1];
            }
        }
        for (int x = 0; x < n; ++x) {
            for (int y = 0; y < n; ++y) {
                if (x == 0 && y == 0) continue;
                else if (x == 0) pref[x][y] += pref[x][y - 1];
                else if (y == 0) pref[x][y] += pref[x - 1][y];
                else pref[x][y] += pref[x - 1][y] + pref[x][y - 1] - pref[x - 1][y - 1];
            }
        }
        for (int x = 0; x < n; ++x) {
            for (int y = 0; y < n; ++y) {
                if (cnt - pref[x][y] == k || cnt - pref[x][y] + 1 == k) {
                    cout << 1;
                    return;
                }
            }
        }
        for (int i = 0; i <= n; ++i) {
            for (int j = 0; j <= n; ++j) {
                pref[i][j] = 0;
            }
        }
    }
    cout << 2;
}

int main() {
    if (1) {
        ios_base::sync_with_stdio(false);
        cin.tie(nullptr);
        cout.tie(nullptr);
    }
    if (1) {
        int t = 1;
        //   cin >> t;
        while (t--) {
            solve1();
        }
    }

    return 0;
}
